1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	const PROCESSING_FEE = 5;
52	
53	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	// Charged on every quote, unconditionally — it is the cost of assessing the
63	// items, not a penalty for being a new customer. Named "first insurance" in
64	// some of the domain material, which misleads: it does not depend on customer
65	// history or on the quote's position in the scenario.
66	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
67	
68	const percentOf = (amount: number, percent: number): number =>
69	  (amount * percent) / 100;
70	
71	const itemBasePremium = (item: Item): number =>
72	  BASE_PREMIUM_BY_TYPE[item.type];
73	
74	const BLOCK_SIZE = 3;
75	
76	const BLOCK_PREMIUM = 60;
77	
78	const sumOf = (amounts: number[]): number =>
79	  amounts.reduce((sum, amount) => sum + amount, 0);
80	
81	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
82	
83	const sumOfItemBasePremiums = (items: Item[]): number =>
84	  sumOf(items.map(itemBasePremium));
85	
86	// Items of the same type are "alike" and are priced together, so the policy
87	// base premium is computed group by group rather than item by item.
88	const alikeGroups = (items: Item[]): Item[][] => {
89	  const groupsByType = new Map<string, Item[]>();
90	
91	  for (const item of items) {
92	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
93	  }
94	
95	  return [...groupsByType.values()];
96	};
97	
98	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
99	  formsABlock(alikeItems)
100	    ? BLOCK_PREMIUM
101	    : sumOfItemBasePremiums(alikeItems);
102	
103	const policyBasePremium = (items: Item[]): number =>
104	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
105	
106	const roundPremiumInMHPCOsFavor = (amount: number): number =>
107	  Math.ceil(amount);
108	
109	// The inputs a single quote is computed from: `items` drives the base premium
110	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
111	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
112	// general — a claim step is not a contract and must not trigger the follow-up
113	// discount.
114	type QuoteRequest = {
115	  customer: Customer;
116	  items: Item[];
117	  precedingQuoteCount: number;
118	};
119	
120	const LOYALTY_YEARS = 2;
121	
122	const LOYALTY_DISCOUNT_PERCENT = 20;
123	
124	// Modifier percents are signed so surcharges and discounts can be summed
125	// uniformly; a discount enters the sum as its negation.
126	const asDiscount = (percent: number): number => -percent;
127	
128	const isLoyal = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
130	
131	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
132	
133	const isFollowUpContract = (request: QuoteRequest): boolean =>
134	  request.precedingQuoteCount > 0;
135	
136	const policyModifierPercents = (request: QuoteRequest): number[] => [
137	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
138	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
139	  ...(isFollowUpContract(request)
140	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
141	    : []),
142	];
143	
144	// Policy-wide modifiers do NOT compound: each is an independent percentage of
145	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
146	// would give a different, wrong answer.
147	const applyPolicyModifiers = (
148	  basePremium: number,
149	  request: QuoteRequest,
150	): number =>
151	  basePremium +
152	  sumOf(
153	    policyModifierPercents(request).map((percent) =>
154	      percentOf(basePremium, percent),
155	    ),
156	  );
157	
158	const CURSE_SURCHARGE_PERCENT = 50;
159	
160	const HIGH_ENCHANTMENT_LEVEL = 5;
161	
162	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
163	
164	const isHighlyEnchanted = (item: Item): boolean =>
165	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
166	
167	const isCursed = (item: Item): boolean => item.cursed === true;
168	
169	type ItemSurchargeRule = {
170	  applies: (item: Item) => boolean;
171	  percent: number;
172	};
173	
174	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
175	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
176	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
177	];
178	
179	// Item-scoped surcharges are charged on the item's own base premium, so they
180	// must NOT go through applyPolicyModifiers.
181	const itemSurcharges = (item: Item): number =>
182	  sumOf(
183	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
184	      percentOf(itemBasePremium(item), rule.percent),
185	    ),
186	  );
187	
188	const policyItemSurcharges = (items: Item[]): number =>
189	  sumOf(items.map(itemSurcharges));
190	
191	const quotePremium = (request: QuoteRequest): number =>
192	  roundPremiumInMHPCOsFavor(
193	    applyPolicyModifiers(policyBasePremium(request.items), request) +
194	      policyItemSurcharges(request.items) +
195	      PROCESSING_FEE,
196	  );
197	
198	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
199	  sword: 1000,
200	  amulet: 600,
201	  staff: 800,
202	  potion: 400,
203	  rune: 250,
204	  moonstone: 250,
205	};
206	
207	const insuranceSum = (items: Item[]): number =>
208	  sumOf(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
209	
210	const CAP_MULTIPLIER = 2;
211	
212	const DEDUCTIBLE = 100;
213	
214	// The deductible applies once per damage event, i.e. per entry in `damages`.
215	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;
216	
217	const isQuote = (step: Step): boolean => step.op === "quote";
218	
219	// What the scenario has accumulated so far. Steps are folded rather than mapped
220	// because a step's result depends on the steps before it: `precedingQuoteCount`
221	// drives the follow-up discount today, and claim steps will thread a remaining
222	// cap through the same carry.
223	type ScenarioState = {
224	  results: StepResult[];
225	  precedingQuoteCount: number;
226	  // Policies created by earlier quote steps, keyed by that step's index — a
227	  // claim names its policy that way (`step.policy`).
228	  policiesByStep: Map<number, Item[]>;
229	};
230	
231	const INITIAL_STATE: ScenarioState = {
232	  results: [],
233	  precedingQuoteCount: 0,
234	  policiesByStep: new Map(),
235	};
236	
237	// Running a step is a state transition: it reads the carry accumulated by the
238	// preceding steps and returns the next carry. Every step kind gets its own
239	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
240	// will be added without touching the quote path.
241	type StepRunner = (
242	  customer: Customer,
243	  state: ScenarioState,
244	  step: Step,
245	  stepIndex: number,
246	) => ScenarioState;
247	
248	const appendResult = (
249	  state: ScenarioState,
250	  result: StepResult,
251	): ScenarioState => ({ ...state, results: [...state.results, result] });
252	
253	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
254	  const items = step.items ?? [];
255	
256	  const premium = quotePremium({
257	    customer,
258	    items,
259	    precedingQuoteCount: state.precedingQuoteCount,
260	  });
261	
262	  return {
263	    ...appendResult(state, { premium }),
264	    precedingQuoteCount: state.precedingQuoteCount + 1,
265	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, items),
266	  };
267	};
268	
269	const runClaimStep: StepRunner = (_customer, state, step) => {
270	  const items = state.policiesByStep.get(step.policy ?? -1) ?? [];
271	  const damages = step.incident?.damages ?? [];
272	
273	  const payout = sumOf(damages.map(damagePayout));
274	  const cap = CAP_MULTIPLIER * insuranceSum(items);
275	
276	  return appendResult(state, { payout, remainingCap: cap - payout });
277	};
278	
279	const runStep: StepRunner = (customer, state, step, stepIndex) =>
280	  isQuote(step)
281	    ? runQuoteStep(customer, state, step, stepIndex)
282	    : runClaimStep(customer, state, step, stepIndex);
283	
284	// The customer is scenario-wide, so it is closed over rather than threaded
285	// through the fold alongside the per-step state.
286	const stepRunnerFor =
287	  (customer: Customer) =>
288	  (state: ScenarioState, step: Step, stepIndex: number) =>
289	    runStep(customer, state, step, stepIndex);
290	
291	export const runScenario = (scenario: Scenario): ScenarioResults => ({
292	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
293	    .results,
294	});
