// A claim names its policy by the index of the quote step that created it. An
// unnamed or unknown policy currently yields no insured items, and so a cap of
// 0 — the pending error-handling tests will replace this with a rejection.
const insuredItemsFor = (state: ScenarioState, step: Step): Item[] =>
  step.policy === undefined ? [] : (state.policiesByStep.get(step.policy) ?? []);

const runClaimStep: StepRunner = (_customer, state, step) => {
  const damages = step.incident?.damages ?? [];

  const payout = sumOf(damages.map(damagePayout));
  const cap = policyCap(insuredItemsFor(state, step));

  return appendResult(state, { payout, remainingCap: cap - payout });
};

